namespace {
constexpr uint64_t kSector=512;
uint32_t crc32(const uint8_t* data,size_t n){uint32_t c=0xffffffffu;for(size_t i=0;i<n;i++){c^=data[i];for(int b=0;b<8;b++)c=(c>>1)^(0xedb88320u&(0u-(c&1u)));}return ~c;}
uint32_t le32(const uint8_t* p){return uint32_t(p[0])|(uint32_t(p[1])<<8)|(uint32_t(p[2])<<16)|(uint32_t(p[3])<<24);}
uint64_t le64(const uint8_t* p){return uint64_t(le32(p))|(uint64_t(le32(p+4))<<32);}
void put32(uint8_t* p,uint32_t v){for(int i=0;i<4;i++)p[i]=uint8_t(v>>(8*i));}
void put64(uint8_t* p,uint64_t v){for(int i=0;i<8;i++)p[i]=uint8_t(v>>(8*i));}
class Sha256{
 static constexpr uint32_t K[64]={0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2};
 std::array<uint32_t,8> h{{0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19}};std::array<uint8_t,64> block{};size_t used=0;uint64_t bytes=0;
 static uint32_t rr(uint32_t x,int n){return(x>>n)|(x<<(32-n));}
 void transform(const uint8_t* b){uint32_t w[64];for(int i=0;i<16;i++)w[i]=(uint32_t(b[i*4])<<24)|(uint32_t(b[i*4+1])<<16)|(uint32_t(b[i*4+2])<<8)|b[i*4+3];for(int i=16;i<64;i++){uint32_t s0=rr(w[i-15],7)^rr(w[i-15],18)^(w[i-15]>>3),s1=rr(w[i-2],17)^rr(w[i-2],19)^(w[i-2]>>10);w[i]=w[i-16]+s0+w[i-7]+s1;}uint32_t a=h[0],bb=h[1],c=h[2],d=h[3],e=h[4],f=h[5],g=h[6],z=h[7];for(int i=0;i<64;i++){uint32_t t1=z+(rr(e,6)^rr(e,11)^rr(e,25))+((e&f)^(~e&g))+K[i]+w[i],t2=(rr(a,2)^rr(a,13)^rr(a,22))+((a&bb)^(a&c)^(bb&c));z=g;g=f;f=e;e=d+t1;d=c;c=bb;bb=a;a=t1+t2;}h[0]+=a;h[1]+=bb;h[2]+=c;h[3]+=d;h[4]+=e;h[5]+=f;h[6]+=g;h[7]+=z;}
public:void update(const uint8_t* p,size_t n){bytes+=n;while(n){size_t k=std::min(n,64-used);std::memcpy(block.data()+used,p,k);used+=k;p+=k;n-=k;if(used==64){transform(block.data());used=0;}}}std::string finish(){uint64_t bits=bytes*8;block[used++]=0x80;if(used>56){while(used<64)block[used++]=0;transform(block.data());used=0;}while(used<56)block[used++]=0;for(int i=7;i>=0;i--)block[used++]=uint8_t(bits>>(i*8));transform(block.data());std::ostringstream o;o<<std::hex<<std::setfill('0');for(uint32_t v:h)o<<std::setw(8)<<v;return o.str();}};
struct Report{std::string format="Unknown",detail="No recognized partition table",sha;uint64_t size=0;bool valid=false;unsigned partitions=0;};
bool read_at(std::ifstream& f,uint64_t off,uint8_t* dst,size_t n){if(off>uint64_t(std::numeric_limits<std::streamoff>::max()))return false;f.clear();f.seekg(static_cast<std::streamoff>(off));f.read(reinterpret_cast<char*>(dst),static_cast<std::streamsize>(n));return size_t(f.gcount())==n;}
void debug(bool on,const std::string& msg){if(on)std::cerr<<"debug: "<<msg<<'\n';}
struct Gpt{uint64_t current=0,backup=0,first=0,last=0,table=0;uint32_t count=0,entry_size=0,table_crc=0;std::vector<uint8_t> entries;};
bool read_gpt(std::ifstream& f,uint64_t size,uint64_t lba,Gpt& g,std::string& err,bool dbg){debug(dbg,"reading GPT header at LBA "+std::to_string(lba));if(lba>std::numeric_limits<uint64_t>::max()/kSector){err="GPT header offset overflow";return false;}std::array<uint8_t,512> h{};if(!read_at(f,lba*kSector,h.data(),h.size())||std::memcmp(h.data(),"EFI PART",8)){err="GPT header signature missing";return false;}uint32_t hs=le32(h.data()+12),saved=le32(h.data()+16);if(hs<92||hs>512){err="Invalid GPT header size";return false;}auto copy=h;std::fill(copy.begin()+16,copy.begin()+20,0);if(crc32(copy.data(),hs)!=saved){err="GPT header CRC mismatch";return false;}g.current=le64(h.data()+24);g.backup=le64(h.data()+32);g.first=le64(h.data()+40);g.last=le64(h.data()+48);g.table=le64(h.data()+72);g.count=le32(h.data()+80);g.entry_size=le32(h.data()+84);g.table_crc=le32(h.data()+88);uint64_t sectors=size/kSector;if(g.current!=lba||g.backup>=sectors||g.backup==g.current){err="GPT current/backup LBA fields invalid";return false;}if(g.first>g.last||g.last>=sectors||g.first<=1){err="GPT usable partition range invalid";return false;}if(g.entry_size<128||g.entry_size%8||!g.count||g.count>16384){err="GPT partition-entry geometry invalid";return false;}uint64_t bytes=uint64_t(g.count)*g.entry_size;if(g.table>std::numeric_limits<uint64_t>::max()/kSector){err="GPT entry-table offset overflow";return false;}uint64_t off=g.table*kSector;if(off>size||bytes>size-off||bytes>64*1024*1024){err="GPT entry table outside image or too large";return false;}g.entries.resize(size_t(bytes));if(!read_at(f,off,g.entries.data(),g.entries.size())){err="Cannot read GPT entry table";return false;}if(crc32(g.entries.data(),g.entries.size())!=g.table_crc){err="GPT entry-table CRC mismatch";return false;}return true;}
Report analyze(const std::string& path,bool dbg){debug(dbg,"opening input read-only: "+path);std::ifstream f(path,std::ios::binary);if(!f)throw std::runtime_error("Cannot open input image");f.seekg(0,std::ios::end);auto end=f.tellg();if(end<0)throw std::runtime_error("Cannot determine image size");Report r;r.size=uint64_t(end);f.seekg(0);Sha256 sha;std::vector<uint8_t> buf(1024*1024);uint64_t done=0;while(f){f.read(reinterpret_cast<char*>(buf.data()),std::streamsize(buf.size()));auto n=f.gcount();if(n>0){sha.update(buf.data(),size_t(n));done+=uint64_t(n);}}if(!f.eof())throw std::runtime_error("Error while reading image");r.sha=sha.finish();debug(dbg,"hashed "+std::to_string(done)+" bytes");if(r.size<kSector){r.detail="Image is smaller than one 512-byte sector";return r;}std::array<uint8_t,512> m{};if(!read_at(f,0,m.data(),m.size()))throw std::runtime_error("Cannot read first sector");bool mbrsig=m[510]==0x55&&m[511]==0xaa;
 if(r.size>=2*kSector){std::array<uint8_t,8>s{};if(read_at(f,kSector,s.data(),s.size())&&!std::memcmp(s.data(),"EFI PART",8)){r.format="GPT";Gpt p,b;std::string err;if(!read_gpt(f,r.size,1,p,err,dbg)){r.detail=err;return r;}if(p.backup!=r.size/kSector-1){r.detail="Primary GPT does not point to final image sector";return r;}uint64_t table_sectors=(uint64_t(p.count)*p.entry_size+kSector-1)/kSector;if(p.table<=p.current||p.table>=p.first||table_sectors>p.first-p.table||p.table+table_sectors-1>=p.backup){r.detail="Primary GPT entry table overlaps header or usable space";return r;}if(!read_gpt(f,r.size,p.backup,b,err,dbg)){r.detail="Backup GPT: "+err;return r;}if(b.backup!=p.current||b.first!=p.first||b.last!=p.last||b.count!=p.count||b.entry_size!=p.entry_size||b.table_crc!=p.table_crc||b.entries!=p.entries){r.detail="Primary and backup GPT metadata disagree";return r;}uint64_t bsectors=(uint64_t(b.count)*b.entry_size+kSector-1)/kSector;if(b.table<=b.last||b.table>=b.current||bsectors>b.current-b.table){r.detail="Backup GPT table overlaps usable space or header";return r;}std::vector<std::pair<uint64_t,uint64_t>> ranges;for(uint32_t i=0;i<p.count;i++){const uint8_t* e=p.entries.data()+size_t(i)*p.entry_size;bool empty=true;for(int j=0;j<16;j++)if(e[j]){empty=false;break;}if(empty)continue;uint64_t first=le64(e+32),last=le64(e+40);if(first<p.first||last>p.last||first>last){r.detail="GPT partition entry has invalid bounds";return r;}ranges.emplace_back(first,last);}std::sort(ranges.begin(),ranges.end());for(size_t i=1;i<ranges.size();i++)if(ranges[i].first<=ranges[i-1].second){r.detail="GPT partitions overlap";return r;}r.partitions=unsigned(ranges.size());r.valid=true;r.detail="Primary/backup GPT headers and tables pass CRC/consistency checks; partition ranges valid";return r;}}
 if(mbrsig){r.format="MBR";unsigned active=0;std::vector<std::pair<uint64_t,uint64_t>> ranges;for(int i=0;i<4;i++){const uint8_t* e=&m[446+i*16];if(e[0]!=0&&e[0]!=0x80){r.detail="Invalid MBR boot flag";return r;}if(e[0]==0x80)active++;uint32_t start=le32(e+8),len=le32(e+12);if(!len)continue;uint64_t finish=uint64_t(start)+len;if(!start||finish>r.size/kSector){r.detail="MBR partition has invalid or out-of-image bounds";return r;}ranges.emplace_back(start,finish-1);}if(active>1){r.detail="Multiple active MBR partitions";return r;}std::sort(ranges.begin(),ranges.end());for(size_t i=1;i<ranges.size();i++)if(ranges[i].first<=ranges[i-1].second){r.detail="MBR partitions overlap";return r;}r.partitions=unsigned(ranges.size());r.valid=true;r.detail=std::to_string(r.partitions)+" MBR partition(s); signature, flags, bounds and overlap checks pass";return r;}r.detail="No valid MBR signature or GPT header found";return r;}
std::string escape_json(const std::string& s){std::ostringstream o;for(unsigned char c:s){switch(c){case '\\':o<<"\\\\";break;case '"':o<<"\\\"";break;case '\n':o<<"\\n";break;case '\r':o<<"\\r";break;case '\t':o<<"\\t";break;default:if(c<32)o<<"\\u"<<std::hex<<std::setw(4)<<std::setfill('0')<<unsigned(c)<<std::dec;else o<<char(c);}}return o.str();}
std::string report_json(const std::string& path,const Report& r,bool has_expected,bool match){std::ostringstream o;o<<"{\"file\":\""<<escape_json(path)<<"\",\"size_bytes\":"<<r.size<<",\"sha256\":\""<<r.sha<<"\",\"partition_table\":\""<<escape_json(r.format)<<"\",\"partitions\":"<<r.partitions<<",\"valid\":"<<(r.valid?"true":"false")<<",\"detail\":\""<<escape_json(r.detail)<<"\",\"expected_sha256_match\":";if(!has_expected)o<<"null";else o<<(match?"true":"false");return o.str()+"}";}
void usage(){std::cerr<<"Rescate USB 0.3.0 — diagnóstico de imágenes, solo lectura\nUso: rescateusb <imagen> [--json] [--json-out ARCHIVO] [--expected-sha256 HASH] [--debug]\n     rescateusb --self-test\n";}
void self_test(){const std::string p="rescateusb-selftest.img";auto expect=[&](bool ok,const char* msg){if(!ok)throw std::runtime_error(std::string("Self-test failed: ")+msg);};Sha256 empty,abc;expect(empty.finish()=="e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855","SHA-256 empty vector");std::string a="abc";abc.update(reinterpret_cast<const uint8_t*>(a.data()),a.size());expect(abc.finish()=="ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad","SHA-256 abc vector");
 auto save=[&](const std::vector<uint8_t>& v){std::ofstream o(p,std::ios::binary);o.write(reinterpret_cast<const char*>(v.data()),std::streamsize(v.size()));if(!o)throw std::runtime_error("Cannot create self-test image");};std::vector<uint8_t> m(512);m[510]=0x55;m[511]=0xaa;m[446+4]=0x83;put32(&m[454],1);put32(&m[458],100);save(m);auto r=analyze(p,false);expect(r.valid&&r.format=="MBR"&&r.partitions==1,"valid MBR");m[462]=0x80;m[466]=0x83;put32(&m[470],50);put32(&m[474],100);save(m);r=analyze(p,false);expect(!r.valid&&r.detail.find("overlap")!=std::string::npos,"overlapping MBR rejection");
 std::vector<uint8_t> img(100*512);img[510]=0x55;img[511]=0xaa;img[450]=0xee;put32(&img[454],1);put32(&img[458],99);std::vector<uint8_t> entries(128*128);entries[0]=0x28;put64(entries.data()+32,40);put64(entries.data()+40,50);uint32_t ec=crc32(entries.data(),entries.size());std::copy(entries.begin(),entries.end(),img.begin()+2*512);std::copy(entries.begin(),entries.end(),img.begin()+67*512);auto hdr=[&](uint64_t cur,uint64_t backup,uint64_t table){uint8_t* h=img.data()+cur*512;std::memcpy(h,"EFI PART",8);put32(h+8,0x00010000);put32(h+12,92);put64(h+24,cur);put64(h+32,backup);put64(h+40,34);put64(h+48,66);put64(h+72,table);put32(h+80,128);put32(h+84,128);put32(h+88,ec);put32(h+16,crc32(h,92));};hdr(1,99,2);hdr(99,1,67);save(img);r=analyze(p,false);expect(r.valid&&r.format=="GPT"&&r.partitions==1,"valid GPT and backup");
 auto corrupt=img;corrupt[99*512+16]^=1;save(corrupt);r=analyze(p,false);expect(!r.valid,"corrupt GPT backup CRC");corrupt=img;corrupt[99*512+32]=2;put32(&corrupt[99*512+16],0);put32(&corrupt[99*512+16],crc32(corrupt.data()+99*512,92));save(corrupt);r=analyze(p,false);expect(!r.valid,"GPT primary/backup disagreement");
 std::remove(p.c_str());std::cout<<"Self-test passed: SHA-256 vectors; valid, overlapping MBR; valid GPT, backup CRC and metadata mismatch\n";}
}
int main(int argc,char** argv){try{if(argc==2&&std::string(argv[1])=="--self-test"){self_test();return 0;}if(argc<2){usage();return 2;}std::string path=argv[1],expected,jsonout;bool json=false,dbg=false;for(int i=2;i<argc;i++){std::string x=argv[i];if(x=="--json")json=true;else if(x=="--debug")dbg=true;else if((x=="--expected-sha256"||x=="--json-out")&&i+1<argc){std::string v=argv[++i];if(x=="--expected-sha256")expected=v;else jsonout=v;}else{usage();return 2;}}debug(dbg,"diagnostic started");Report r=analyze(path,dbg);bool match=true;if(!expected.empty()){for(char& c:expected)c=char(std::tolower(static_cast<unsigned char>(c)));match=expected.size()==64&&expected==r.sha;}std::string js=report_json(path,r,!expected.empty(),match);if(!jsonout.empty()){std::ofstream out(jsonout,std::ios::binary);if(!out)throw std::runtime_error("Cannot create JSON report");out<<js<<'\n';if(!out)throw std::runtime_error("Cannot write JSON report");debug(dbg,"JSON report written to "+jsonout);}if(json)std::cout<<js<<'\n';else{std::cout<<"Rescate USB — diagnóstico de solo lectura\nArchivo: "<<path<<"\nTamaño: "<<r.size<<" bytes\nSHA-256: "<<r.sha<<"\nTabla: "<<r.format<<"\nParticiones: "<<r.partitions<<"\nResultado: "<<(r.valid?"VÁLIDO":"REVISAR")<<" — "<<r.detail<<'\n';if(!expected.empty())std::cout<<"Hash esperado: "<<(match?"coincide":"NO coincide")<<'\n';}if(!match)return 3;return r.valid?0:1;}catch(const std::exception& e){std::cerr<<"Error: "<<e.what()<<'\n';return 2;}}
